INSERT INTO public.dev_tasks(id,payload) VALUES('platform-42',jsonb_build_object('id','platform-42','title','Simplify and enrich object creation flow','description','Review the object creation process, especially when adding the first object while creating a museum. Make it more intuitive (guided steps, clear required vs optional fields, inline image upload, sensible defaults) and capture richer data: condition, provenance, acquisition date/price, dimensions, materials, serial number, tags and story notes. Keep existing records compatible.','area','Collector','priority','P1','status','todo','impact',4,'effort',3,'rank',72,'createdAt','2026-11-03')) ON CONFLICT (id) DO NOTHING;